import type { QuestionSet } from './session.ts';

// The legacy app's built-in set ("Legacy Reflections"), English texts and ids
// carried over from emotely-legacy's legacyQuestionSet.
export const defaultQuestionSet: QuestionSet = {
  id: 'KT9cr1mEoilCTNC6o3mK',
  name: 'Legacy Reflections',
  questions: [
    { id: '15CjDQMbgiupVv4EGKWh', text: 'What did you learn today?', answer_type: 'text_list' },
    {
      id: 'CpUKaQcSH9u4La8Y2lBM',
      text: 'What was the best thing that happened today?',
      answer_type: 'longtext',
    },
    {
      id: 'I3QkqSeXmGSX47IAlih4',
      text: 'Which color(s) best describe your day?',
      answer_type: 'color',
    },
    {
      id: 'N5dhXuRDmJ6DRRGDxcuB',
      text: 'Which emojis describe your mood during different parts of your day?',
      answer_type: 'emoji',
    },
    {
      id: 'NUy0Q6sAiHQjteaSyjz4',
      text: 'How productive did you feel today?',
      answer_type: 'rating',
    },
    {
      id: 'O3ewi4LNh8RHoFo45Je3',
      text: 'How satisfied are you with your day?',
      answer_type: 'rating',
    },
    {
      id: 'V7N4ipTxlaqxXlRHEAUE',
      text: 'How much appreciation did you feel for the small victories or moments in your life today?',
      answer_type: 'rating',
    },
    {
      id: 'ZP1r3kAnMd9XZ1rU1sem',
      text: "List down at least 3 things that you're grateful for today.",
      answer_type: 'text_list',
      min_answers: 3,
    },
    {
      id: 'f3GVndW7IGrd8qb3icvf',
      text: 'How well did your actions today align with the goals you want to achieve?',
      answer_type: 'rating',
    },
    {
      id: 'g3xpuKYjz9aljHZhHkOu',
      text: "Share about someone you're grateful for today and how they positively impact your life.",
      answer_type: 'longtext',
    },
  ],
};

import { createInterface } from 'node:readline/promises';
import type { JSONValue } from 'ai';
import { defaultQuestionSet } from './default-question-set.ts';
import { runSession, type SessionClient } from './session.ts';

try {
  process.loadEnvFile(new URL('../.env.local', import.meta.url).pathname);
} catch {
  // fine — key may come from the environment
}

// ponytail: model swap is one env var; PostHog flag payload takes over in issue #5.
const model = process.env.EMOTELY_MODEL ?? 'zai/glm-4.7-flash';

const rl = createInterface({ input: process.stdin, output: process.stdout });

const hints: Record<string, string> = {
  text_list: 'one or more answers, comma-separated',
  longtext: 'one answer, free text',
  rating: 'a number from 1 to 10',
  emoji: 'one or more emojis, comma-separated',
  color: 'one or more hex colors like #FF0000, comma-separated',
};

const client: SessionClient = {
  askQuestion: async (input) => {
    const raw = await rl.question(`\n${input.question}\n(${hints[input.answer_type]}) > `);
    if (input.answer_type === 'rating') return Number(raw.trim());
    if (input.answer_type === 'longtext') return raw.trim();
    return raw.split(',').map((s) => s.trim()).filter(Boolean) as JSONValue;
  },
};

console.log(`emotely journaling session — set "${defaultQuestionSet.name}", model ${model}`);
const result = await runSession({ questionSet: defaultQuestionSet, client, model });
rl.close();

console.log('\n--- journal entry ---');
console.log(result.summary);
console.log('\n--- recorded answers ---');
console.log(JSON.stringify(result.answers, null, 2));

export { defaultQuestionSet } from './default-question-set.ts';
