import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { MODEL_RATES, sessionCostUsd } from "./cost.ts";

describe("sessionCostUsd", () => {
  it("prices summed token usage at the model's per-million rates", () => {
    // Worked example: 100k in + 10k out at glm-4.7-flash rates
    // (0.07 $/M input, 0.40 $/M output, gateway catalog 2026-08-20)
    // = 0.1 * 0.07 + 0.01 * 0.40 = 0.007 + 0.004 = 0.011
    const usages = [
      { inputTokens: 60_000, outputTokens: 4_000 },
      { inputTokens: 40_000, outputTokens: 6_000 },
    ];
    assert.equal(
      sessionCostUsd(usages, MODEL_RATES["zai/glm-4.7-flash"]!),
      0.011,
    );
  });

  it("throws for a model with no known rates", () => {
    assert.equal(MODEL_RATES["not/a-model"], undefined);
  });
});

export type ModelRates = {
  /** USD per million input tokens */
  inputPerM: number;
  /** USD per million output tokens */
  outputPerM: number;
};

// Verified against the gateway model catalog on 2026-08-20; re-verify in #4's
// benchmark rather than trusting these to stay current.
export const MODEL_RATES: Record<string, ModelRates> = {
  "zai/glm-4.7-flash": { inputPerM: 0.07, outputPerM: 0.4 },
};

export function sessionCostUsd(
  usages: Array<{ inputTokens: number; outputTokens: number }>,
  rates: ModelRates,
): number {
  const input = usages.reduce((sum, u) => sum + u.inputTokens, 0);
  const output = usages.reduce((sum, u) => sum + u.outputTokens, 0);
  return (input * rates.inputPerM + output * rates.outputPerM) / 1_000_000;
}

