import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { MockLanguageModelV4 } from "ai/test";
import { judgeSession } from "./judge.ts";

const verdictJson = JSON.stringify({
  verdicts: [
    { rubric: "greets the user by name", pass: true, reason: "Greets Pete." },
    {
      rubric: "asks only about the current question",
      pass: false,
      reason: "Drifted into unrelated advice.",
    },
  ],
});

const model = new MockLanguageModelV4({
  doGenerate: async () => ({
    content: [{ type: "text" as const, text: verdictJson }],
    finishReason: { unified: "stop" as const, raw: undefined },
    usage: {
      inputTokens: { total: 1, noCache: 1, cacheRead: undefined, cacheWrite: undefined },
      outputTokens: { total: 1, text: 1, reasoning: undefined },
    },
    warnings: [],
  }),
});

describe("judgeSession", () => {
  it("returns one validated verdict per rubric from a single model call", async () => {
    const verdicts = await judgeSession({
      model,
      transcript: "assistant: Hi Pete! ...",
      rubrics: ["greets the user by name", "asks only about the current question"],
    });

    assert.equal(verdicts.length, 2);
    assert.deepEqual(
      verdicts.map((v) => v.pass),
      [true, false],
    );
    assert.equal(verdicts[1]?.reason, "Drifted into unrelated advice.");
  });
});

import { generateObject, type LanguageModel } from "ai";
import { z } from "zod";

const verdictSchema = z.object({
  verdicts: z.array(
    z.object({
      rubric: z.string(),
      pass: z.boolean(),
      reason: z.string(),
    }),
  ),
});

export type Verdict = z.infer<typeof verdictSchema>["verdicts"][number];

/** One structured judge call covering every rubric for a session transcript. */
export async function judgeSession(opts: {
  model: LanguageModel;
  transcript: string;
  rubrics: string[];
}): Promise<Verdict[]> {
  const { model, transcript, rubrics } = opts;
  const { object } = await generateObject({
    model,
    schema: verdictSchema,
    prompt: `You are grading a journaling-assistant conversation against rubrics.
For EACH rubric, decide pass/fail for the assistant's behavior in the transcript
and give a one-sentence reason. Return one verdict per rubric, in order.

Rubrics:
${rubrics.map((r, i) => `${i + 1}. ${r}`).join("\n")}

Transcript:
${transcript}`,
  });
  return object.verdicts;
}

